CREATE TABLE IF NOT EXISTS knowledge_point (id BIGINT PRIMARY KEY AUTO_INCREMENT,parent_id BIGINT DEFAULT NULL,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,exam_type VARCHAR(32) NOT NULL,level INT NOT NULL,sort_no INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',importance DECIMAL(5,2) NOT NULL DEFAULT 1.00,improvement_potential DECIMAL(5,2) NOT NULL DEFAULT 0.50,transfer_value DECIMAL(5,2) NOT NULL DEFAULT 0.50,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_kp_parent(parent_id));
CREATE TABLE IF NOT EXISTS question (id BIGINT PRIMARY KEY AUTO_INCREMENT,question_type VARCHAR(32) NOT NULL,stem TEXT NOT NULL,answer VARCHAR(500) NOT NULL,analysis TEXT,difficulty_expected DECIMAL(5,2) NOT NULL DEFAULT 50,difficulty_calibrated DECIMAL(5,2),standard_time_seconds INT NOT NULL DEFAULT 60,source_type VARCHAR(32) NOT NULL,source_year INT,source_exam VARCHAR(100),source_name VARCHAR(255),source_level CHAR(1) NULL,usage_type VARCHAR(32) NOT NULL DEFAULT 'TRAINING',quality_score DECIMAL(5,2),status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',version INT NOT NULL DEFAULT 1,content_hash CHAR(64),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_question_hash(content_hash));
CREATE TABLE IF NOT EXISTS question_option (id BIGINT PRIMARY KEY AUTO_INCREMENT,question_id BIGINT NOT NULL,option_key VARCHAR(8) NOT NULL,option_text TEXT NOT NULL,sort_no INT NOT NULL,UNIQUE KEY uk_question_option(question_id,option_key));
CREATE TABLE IF NOT EXISTS question_knowledge (id BIGINT PRIMARY KEY AUTO_INCREMENT,question_id BIGINT NOT NULL,knowledge_point_id BIGINT NOT NULL,relation_type VARCHAR(20) NOT NULL,weight DECIMAL(5,2) NOT NULL DEFAULT 1,UNIQUE KEY uk_question_knowledge(question_id,knowledge_point_id));
CREATE TABLE IF NOT EXISTS media_asset (id BIGINT PRIMARY KEY AUTO_INCREMENT,storage_type VARCHAR(20) NOT NULL DEFAULT 'LOCAL',storage_path VARCHAR(500) NOT NULL,file_name VARCHAR(255) NOT NULL,file_hash CHAR(64),mime_type VARCHAR(100),file_size BIGINT,width INT,height INT,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS question_media (id BIGINT PRIMARY KEY AUTO_INCREMENT,question_id BIGINT NOT NULL,media_id BIGINT NOT NULL,role VARCHAR(20) NOT NULL,sort_no INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS answer_record (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,question_id BIGINT NOT NULL,question_version INT NOT NULL,practice_type VARCHAR(20) NOT NULL,user_answer VARCHAR(500),correct_answer_snapshot VARCHAR(500) NOT NULL,is_correct TINYINT(1) NOT NULL,duration_ms BIGINT NOT NULL,standard_time_seconds_snapshot INT NOT NULL,difficulty_snapshot DECIMAL(5,2) NOT NULL,knowledge_snapshot JSON NOT NULL,confidence_type VARCHAR(20) NOT NULL,error_type VARCHAR(20) NOT NULL,answer_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_answer_user_time(user_id,answer_time),INDEX idx_answer_question(question_id),INDEX idx_answer_plan_item(user_id,plan_item_id,question_id));
CREATE TABLE IF NOT EXISTS error_diagnosis (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,answer_record_id BIGINT NOT NULL,question_id BIGINT NOT NULL,knowledge_point_id BIGINT NOT NULL,suspected_cause VARCHAR(200) NOT NULL,evidence_json JSON NOT NULL,confidence DECIMAL(5,2) NOT NULL,confirmed_by_user TINYINT(1),status VARCHAR(30) NOT NULL DEFAULT 'PENDING_CONFIRMATION',occurrence_count INT NOT NULL DEFAULT 1,selected_option_key VARCHAR(8),ai_explanation TEXT,ai_provider VARCHAR(50),ai_model VARCHAR(100),ai_prompt_version VARCHAR(50),ai_confidence DECIMAL(5,2),ai_status VARCHAR(30),ai_raw_response MEDIUMTEXT,ai_request_time DATETIME,ai_latency_ms BIGINT,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_diagnosis_user_kp_cause(user_id,knowledge_point_id,suspected_cause),INDEX idx_diagnosis_answer(answer_record_id),INDEX idx_diagnosis_problem(user_id,knowledge_point_id,status));
CREATE TABLE IF NOT EXISTS ability_profile (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,knowledge_point_id BIGINT NOT NULL,mastery_score DECIMAL(5,2) NOT NULL,speed_score DECIMAL(5,2) NOT NULL,stability_score DECIMAL(5,2) NOT NULL,confidence_score DECIMAL(5,2) NOT NULL,sample_count INT NOT NULL,status VARCHAR(20) NOT NULL,last_practice_time DATETIME,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_ability_user_kp(user_id,knowledge_point_id));
CREATE TABLE IF NOT EXISTS ability_history (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,knowledge_point_id BIGINT NOT NULL,mastery_score DECIMAL(5,2) NOT NULL,speed_score DECIMAL(5,2) NOT NULL,stability_score DECIMAL(5,2) NOT NULL,confidence_score DECIMAL(5,2) NOT NULL,sample_count INT NOT NULL,snapshot_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_history_user_kp(user_id,knowledge_point_id,snapshot_time));
CREATE TABLE IF NOT EXISTS learning_problem (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,problem_type VARCHAR(30) NOT NULL,knowledge_point_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,description VARCHAR(500),severity DECIMAL(5,2) NOT NULL,priority_score DECIMAL(5,2) NOT NULL,status VARCHAR(20) NOT NULL,evidence_json JSON,root_cause VARCHAR(500),discovered_time DATETIME NOT NULL,resolved_time DATETIME,validation_count INT NOT NULL DEFAULT 0,validation_pass_count INT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_problem(user_id,problem_type,knowledge_point_id));
CREATE TABLE IF NOT EXISTS learning_problem_history (id BIGINT PRIMARY KEY AUTO_INCREMENT,learning_problem_id BIGINT NOT NULL,from_status VARCHAR(20),to_status VARCHAR(20) NOT NULL,evidence_json JSON NOT NULL,change_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_problem_history_problem(learning_problem_id,change_time));
CREATE TABLE IF NOT EXISTS daily_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,plan_date DATE NOT NULL,planned_minutes INT NOT NULL,actual_minutes INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,generation_reason VARCHAR(500),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_plan_user_date(user_id,plan_date));
CREATE TABLE IF NOT EXISTS daily_plan_item (id BIGINT PRIMARY KEY AUTO_INCREMENT,plan_id BIGINT NOT NULL,item_type VARCHAR(20) NOT NULL,target_type VARCHAR(30) NOT NULL,target_id BIGINT,learning_problem_id BIGINT,knowledge_point_id BIGINT NOT NULL,purpose VARCHAR(20) NOT NULL,reason VARCHAR(500) NOT NULL,planned_minutes INT NOT NULL,sort_no INT NOT NULL,target_question_count INT NULL,completed_question_count INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_item_plan(plan_id),INDEX idx_item_problem(learning_problem_id),INDEX idx_item_knowledge(knowledge_point_id));
CREATE TABLE IF NOT EXISTS essay_question (id BIGINT PRIMARY KEY AUTO_INCREMENT,topic_knowledge_point_id BIGINT NOT NULL,question_type VARCHAR(32) NOT NULL,material MEDIUMTEXT NOT NULL,prompt TEXT NOT NULL,word_limit_min INT NOT NULL DEFAULT 100,word_limit_max INT NOT NULL DEFAULT 400,standard_time_seconds INT NOT NULL DEFAULT 1200,reference_answer MEDIUMTEXT,reference_points JSON,source_type VARCHAR(32) NOT NULL DEFAULT 'MANUAL',source_year INT,source_exam VARCHAR(100),source_name VARCHAR(255),status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',version INT NOT NULL DEFAULT 1,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_essay_question_topic(topic_knowledge_point_id,status));
CREATE TABLE IF NOT EXISTS essay_answer (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,essay_question_id BIGINT NOT NULL,question_version INT NOT NULL,practice_type VARCHAR(20) NOT NULL,answer_text MEDIUMTEXT NOT NULL,duration_ms BIGINT NOT NULL,word_count INT NOT NULL,submit_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_essay_answer_user_time(user_id,submit_time),INDEX idx_essay_answer_question(essay_question_id));
CREATE TABLE IF NOT EXISTS essay_evaluation (id BIGINT PRIMARY KEY AUTO_INCREMENT,essay_answer_id BIGINT NOT NULL,evaluator VARCHAR(32) NOT NULL,provider VARCHAR(50),model VARCHAR(100),prompt_version VARCHAR(50),request_time DATETIME,latency_ms BIGINT,status VARCHAR(30) NOT NULL,confidence DECIMAL(5,2),raw_response MEDIUMTEXT,failure_message VARCHAR(500),total_score DECIMAL(5,2),dimension_scores JSON,strengths JSON,problems JSON,missing_points JSON,evidence JSON,suggestions JSON,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_evaluation_answer(essay_answer_id,create_time),INDEX idx_evaluation_status(status));
CREATE TABLE IF NOT EXISTS political_topic (id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,knowledge_point_id BIGINT NOT NULL,description VARCHAR(500),status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',sort_no INT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_topic_kp(knowledge_point_id));
CREATE TABLE IF NOT EXISTS reading_material (id BIGINT PRIMARY KEY AUTO_INCREMENT,topic_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,source VARCHAR(200),publish_date DATE,content MEDIUMTEXT NOT NULL,core_view TEXT,problem TEXT,cause TEXT,solution TEXT,policy_logic TEXT,standard_expressions JSON,cases JSON,applicable_essay_themes JSON,topic_candidates JSON,ai_confidence DECIMAL(5,2),ai_provider VARCHAR(50),ai_model VARCHAR(100),ai_prompt_version VARCHAR(50),ai_status VARCHAR(30),ai_raw_response MEDIUMTEXT,ai_request_time DATETIME,ai_latency_ms BIGINT,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_material_topic(topic_id,status));
CREATE TABLE IF NOT EXISTS reading_record (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,material_id BIGINT NOT NULL,read_status VARCHAR(20) NOT NULL DEFAULT 'READING',favorite TINYINT(1) NOT NULL DEFAULT 0,mastery_level VARCHAR(20) NOT NULL DEFAULT 'UNMASTERED',duration_ms BIGINT,first_read_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_read_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_reading_user_material(user_id,material_id),INDEX idx_reading_user_status(user_id,read_status));
CREATE TABLE IF NOT EXISTS ai_provider_config (id BIGINT PRIMARY KEY AUTO_INCREMENT,provider_code VARCHAR(32) NOT NULL UNIQUE,enabled TINYINT(1) NOT NULL DEFAULT 0,model VARCHAR(100),custom_model VARCHAR(100),base_url VARCHAR(255),api_key_cipher TEXT,masked_key VARCHAR(64),is_default TINYINT(1) NOT NULL DEFAULT 0,last_test_status VARCHAR(32),last_test_message VARCHAR(500),last_test_time DATETIME,last_test_latency_ms BIGINT,last_test_model VARCHAR(100),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_source (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,base_url VARCHAR(500) NOT NULL,source_type VARCHAR(32) NOT NULL DEFAULT 'GOVERNMENT',exam_type VARCHAR(32) NOT NULL DEFAULT 'GK',trust_level CHAR(1) NOT NULL DEFAULT 'B',enabled TINYINT(1) NOT NULL DEFAULT 1,crawl_strategy VARCHAR(32) NOT NULL DEFAULT 'LINK_SCAN',last_crawl_time DATETIME,status VARCHAR(20) NOT NULL DEFAULT 'IDLE',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_content_source_url(base_url(255)));
CREATE TABLE IF NOT EXISTS content_staging (id BIGINT PRIMARY KEY AUTO_INCREMENT,source_id BIGINT NOT NULL,source_url VARCHAR(760) NOT NULL,site_name VARCHAR(100),publish_org VARCHAR(200),publish_time DATETIME,crawl_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,title VARCHAR(300),original_file_name VARCHAR(255),mime_type VARCHAR(100),file_size BIGINT,file_hash CHAR(64),content_hash CHAR(64),exam_type VARCHAR(32),source_year INT,source_type VARCHAR(32),trust_level CHAR(1),file_path VARCHAR(500),parsed_text MEDIUMTEXT,status VARCHAR(32) NOT NULL DEFAULT 'DISCOVERED',fail_reason VARCHAR(500),imported_type VARCHAR(32),imported_id BIGINT,review_note VARCHAR(500),quality_score DECIMAL(5,2),quality_confidence DECIMAL(5,2),quality_issues VARCHAR(500),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_staging_url(source_url(255)),INDEX idx_staging_source(source_id,status),INDEX idx_staging_file_hash(file_hash),INDEX idx_staging_content_hash(content_hash),INDEX idx_staging_status(status));
CREATE TABLE IF NOT EXISTS content_crawl_log (id BIGINT PRIMARY KEY AUTO_INCREMENT,source_id BIGINT NOT NULL,source_name VARCHAR(200),status VARCHAR(20) NOT NULL,discovered INT NOT NULL DEFAULT 0,downloaded INT NOT NULL DEFAULT 0,parsed INT NOT NULL DEFAULT 0,imported INT NOT NULL DEFAULT 0,duplicates INT NOT NULL DEFAULT 0,needs_review INT NOT NULL DEFAULT 0,failed INT NOT NULL DEFAULT 0,message VARCHAR(500),start_time DATETIME NOT NULL,end_time DATETIME,INDEX idx_crawl_log_source(source_id,start_time));
CREATE TABLE IF NOT EXISTS mock_paper (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(200) NOT NULL,exam_type VARCHAR(32) NOT NULL,source_year INT,source VARCHAR(255),usage_type VARCHAR(32) NOT NULL DEFAULT 'MOCK_RESERVED',duration_minutes INT NOT NULL,total_score DECIMAL(8,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mock_paper_section (id BIGINT PRIMARY KEY AUTO_INCREMENT,paper_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,section_code VARCHAR(64) NOT NULL,knowledge_point_id BIGINT NOT NULL,sort_no INT NOT NULL,score DECIMAL(8,2) NOT NULL,INDEX idx_mock_section_paper(paper_id));
CREATE TABLE IF NOT EXISTS mock_paper_item (id BIGINT PRIMARY KEY AUTO_INCREMENT,paper_id BIGINT NOT NULL,section_id BIGINT NOT NULL,item_type VARCHAR(20) NOT NULL,question_id BIGINT,essay_question_id BIGINT,sort_no INT NOT NULL,score DECIMAL(8,2) NOT NULL,UNIQUE KEY uk_mock_paper_item(paper_id,sort_no),INDEX idx_mock_item_section(section_id));
CREATE TABLE IF NOT EXISTS mock_session (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,paper_id BIGINT NOT NULL,start_time DATETIME NOT NULL,submit_time DATETIME,duration_ms BIGINT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,total_score DECIMAL(8,2),completion_rate DECIMAL(5,2),submit_type VARCHAR(20),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_mock_session_user(user_id,start_time),INDEX idx_mock_session_paper(paper_id));
CREATE TABLE IF NOT EXISTS mock_answer (id BIGINT PRIMARY KEY AUTO_INCREMENT,session_id BIGINT NOT NULL,paper_item_id BIGINT NOT NULL,question_id BIGINT,essay_question_id BIGINT,section_code VARCHAR(64) NOT NULL,answer_order INT,user_answer MEDIUMTEXT,correct_answer_snapshot VARCHAR(500),result_status VARCHAR(20) NOT NULL,duration_ms BIGINT NOT NULL DEFAULT 0,start_time DATETIME,submit_time DATETIME,word_count INT,score DECIMAL(8,2),evaluation_json JSON,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_mock_answer_session_item(session_id,paper_item_id),INDEX idx_mock_answer_session(session_id));
CREATE TABLE IF NOT EXISTS mock_result (id BIGINT PRIMARY KEY AUTO_INCREMENT,session_id BIGINT NOT NULL UNIQUE,total_score DECIMAL(8,2) NOT NULL,accuracy_rate DECIMAL(5,2) NOT NULL,completion_rate DECIMAL(5,2) NOT NULL,total_duration_ms BIGINT NOT NULL,section_stats_json JSON NOT NULL,calibration_json JSON NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
